      "kind": "dev",
      "methods": {
        "accrueInterestToFeeRecipient(address[])": {
          "params": {
            "tokens": "List of addresses of tokens to accrue interest for"
          },
          "returns": {
            "balances": "Amounts of interest accrued"
          }
        },
        "authority()": {
          "details": "Returns the current authority."
        },
        "constructor": {
          "custom:oz-upgrades-unsafe-allow": "constructor"
        },
        "flashFee(address,uint256)": {
          "details": "The fee to be charged for a given loan.",
          "params": {
            "amount": "The amount of tokens lent.",
            "token": "The loan currency."
          },
          "returns": {
            "_0": "The amount of `token` to be charged for the loan, on top of the returned principal."
          }
        },
        "flashLoan(address,address,uint256,bytes)": {
          "details": "Initiate a flash loan.",
          "params": {
            "amount": "The amount of tokens lent.",
            "data": "Arbitrary data structure, intended to contain user-defined parameters.",
            "receiver": "The receiver of the tokens in the loan, and the receiver of the callback.",
            "token": "The loan currency."
          }
        },
        "initialize(address,address)": {
          "params": {
            "_accessManager": "Access manager address"
          }
        },
        "isConsumingScheduledOp()": {
          "details": "Returns true only in the context of a delayed restricted call, at the moment that the scheduled operation is being consumed. Prevents denial of service for delayed restricted calls in the case that the contract performs attacker controlled calls."
        },
        "maxFlashLoan(address)": {
          "details": "The amount of currency available to be lended.",
          "params": {
            "token": "The loan currency."
          },
          "returns": {
            "_0": "The amount of `token` that can be borrowed."
          }
        },
        "proxiableUUID()": {
          "details": "Implementation of the ERC-1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
        },
        "setAuthority(address)": {
          "details": "Transfers control to a new authority. The caller must be the current authority."
        },
        "setFlashLoanFeeRecipient(address)": {
          "params": {
            "_newFlashLoanFeeRecipient": "New flash loan fee recipient"
          }
        },
        "setFlashLoanParameters(address,uint16,uint256,bool)": {
          "details": "Setting a `maxBorrowable` parameter equal to 0 is a way to pause the functionalityParameters can only be modified for whitelisted tokens",
          "params": {
            "_feesRate": "New flash loan fee for this token (in basic point)",
            "_maxBorrowable": "Maximum amount that can be borrowed in a single flash loan",
            "_token": "token to change the parameters for"
          }
        },
        "toggleActiveToken(address)": {
          "params": {
            "_token": "token to toggle the active status for"
          }
        },
        "upgradeToAndCall(address,bytes)": {
          "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
          "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
        }
      },
